static const char nx_str_631[8433] = "// std.stream: buffered readers and writers over files and the standard\n// streams, written in Nexium.\n//\n// `import std.stream` then:\n//\n//     var r = try stream.Reader.open(\"big.log\")\n//     while true {                                    // no whole-file allocation\n//         let line = (try r.read_line()) orelse break\n//         ...\n//     }\n//     r.close()\n//\n//     var w = try stream.Writer.open(\"out.txt\")\n//     try w.write_line(\"hello\")\n//     try w.close()                                    // flushes, then closes\n//\n//     var input = stream.Reader.stdin()\n//     var out = stream.Writer.stdout()\n//     try stream.copy(&mut input, &mut out)\n//     try out.flush()\n//\n// Readers buffer 64 KB at a time; writers gather output and flush when the\n// buffer fills, on `flush`, and on `close`. A Writer must be flushed or\n// closed before the program ends, or buffered output is lost.\n\npub const STDIN: i64 = 1\npub const STDOUT: i64 = 2\npub const STDERR: i64 = 3\n\nconst CHUNK: usize = 65536\n\n/// Reads a handle through a buffer.\npub struct Reader {\n    handle: i64\n    buf: String\n    pos: usize\n    eof: bool\n    owns: bool\n    socket: bool\n}\n\nimpl Reader {\n    /// Open a file for reading.\n    pub fn open(path: []u8) -> !Reader {\n        let h = try io.open(path, \"r\")\n        return Reader{ .handle = h, .buf = String.new(), .pos = 0, .eof = false, .owns = true, .socket = false }\n    }\n\n    /// Standard input.\n    pub fn stdin() -> Reader {\n        return Reader{ .handle = STDIN, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = false }\n    }\n\n    /// Wrap a handle from `io.open`; `close` will not close it.\n    pub fn from_handle(handle: i64) -> Reader {\n        return Reader{ .handle = handle, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = false }\n    }\n\n    /// Wrap a connected socket from `net.connect` or `net.accept`; `close`\n    /// will not close it.\n    pub fn from_socket(sock: i64) -> Reader {\n        return Reader{ .handle = sock, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = true }\n    }\n\n    fn pull(self: *mut Self, n: usize) -> !String {\n        if self.socket { return net.recv(self.handle, n, 0) }\n        return io.read(self.handle, n)\n    }\n\n    // Drop consumed bytes and pull in the next chunk; false at end of input.\n    fn fill(self: *mut Self) -> !bool {\n        if self.eof { return false }\n        if self.pos > 0 {\n            let rest = String.from(self.buf[self.pos..self.buf.len])\n            self.buf = rest\n            self.pos = 0\n        }\n        let chunk = try self.pull(CHUNK)\n        if chunk.len == 0 {\n            self.eof = true\n            return false\n        }\n        self.buf.append(chunk)\n        return true\n    }\n\n    /// The next line without its `\\n` (or `\\r\\n`); null at end of input.\n    pub fn read_line(self: *mut Self) -> !?String {\n        while true {\n            var i = self.pos\n            while i < self.buf.len and self.buf[i] != '\\n' { i += 1 }\n            if i < self.buf.len {\n                var end = i\n                if end > self.pos and self.buf[end - 1] == '\\r' { end -= 1 }\n                let line = String.from(self.buf[self.pos..end])\n                self.pos = i + 1\n                return line\n            }\n            if ! (try self.fill()) {\n                if self.pos < self.buf.len {\n                    var end = self.buf.len\n                    if self.buf[end - 1] == '\\r' { end -= 1 }\n                    let line = String.from(self.buf[self.pos..end])\n                    self.pos = self.buf.len\n                    return line\n                }\n                return null\n            }\n        }\n    }\n\n    /// Up to `n` bytes; empty at end of input.\n    pub fn read(self: *mut Self, n: usize) -> !String {\n        if self.pos >= self.buf.len {\n            if ! (try self.fill()) { return String.new() }\n        }\n        var end = self.pos + n\n        if end > self.buf.len { end = self.buf.len }\n        let out = String.from(self.buf[self.pos..end])\n        self.pos = end\n        return out\n    }\n\n    /// Everything that is left.\n    pub fn read_all(self: *mut Self) -> !String {\n        var out = String.from(self.buf[self.pos..self.buf.len])\n        self.pos = self.buf.len\n        while !self.eof {\n            let chunk = try self.pull(CHUNK)\n            if chunk.len == 0 { break }\n            out.append(chunk)\n        }\n        self.eof = true\n        return out\n    }\n\n    /// Release the file (the standard streams stay open).\n    pub fn close(self: *mut Self) {\n        if self.owns {\n            io.close(self.handle) catch { }\n            self.owns = false\n        }\n        self.eof = true\n    }\n}\n\n/// Buffers output to a handle.\npub struct Writer {\n    handle: i64\n    buf: String\n    owns: bool\n    socket: bool\n}\n\nimpl Writer {\n    /// Create or replace a file.\n    pub fn open(path: []u8) -> !Writer {\n        let h = try io.open(path, \"w\")\n        return Writer{ .handle = h, .buf = String.new(), .owns = true, .socket = false }\n    }\n\n    /// Open a file for appending.\n    pub fn append(path: []u8) -> !Writer {\n        let h = try io.open(path, \"a\")\n        return Writer{ .handle = h, .buf = String.new(), .owns = true, .socket = false }\n    }\n\n    pub fn stdout() -> Writer {\n        return Writer{ .handle = STDOUT, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    pub fn stderr() -> Writer {\n        return Writer{ .handle = STDERR, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    /// Wrap a handle from `io.open`; `close` will not close it.\n    pub fn from_handle(handle: i64) -> Writer {\n        return Writer{ .handle = handle, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    /// Wrap a connected socket; `close` will not close it.\n    pub fn from_socket(sock: i64) -> Writer {\n        return Writer{ .handle = sock, .buf = String.new(), .owns = false, .socket = true }\n    }\n\n    pub fn write(self: *mut Self, data: []u8) -> !void {\n        self.buf.append(data)\n        if self.buf.len >= CHUNK { try self.flush() }\n    }\n\n    pub fn write_line(self: *mut Self, data: []u8) -> !void {\n        try self.write(data)\n        return self.write(\"\\n\")\n    }\n\n    /// Hand buffered output to the handle.\n    pub fn flush(self: *mut Self) -> !void {\n        if self.buf.len > 0 {\n            if self.socket { try net.send(self.handle, self.buf) }\n            else { try io.write(self.handle, self.buf) }\n            self.buf.clear()\n        }\n        if !self.socket { return io.flush(self.handle) }\n    }\n\n    /// Flush, then release the file (the standard streams stay open).\n    pub fn close(self: *mut Self) -> !void {\n        try self.flush()\n        if self.owns {\n            self.owns = false\n            return io.close(self.handle)\n        }\n    }\n}\n\n/// Copy everything from a reader to a writer; the number of bytes moved.\npub fn copy(r: *mut Reader, w: *mut Writer) -> !usize {\n    var total: usize = 0\n    while true {\n        let chunk = try r.read(CHUNK)\n        if chunk.len == 0 { break }\n        try w.write(chunk)\n        total += chunk.len\n    }\n    return total\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"lines and chunks\" {\n    let dir = io.temp_dir()\n    var path = String.from(dir)\n    path.append(\"/nxstream-test.txt\")\n    var w = try Writer.open(path)\n    try w.write_line(\"first\")\n    try w.write(\"second\\r\\n\")\n    try w.write(\"third\")\n    try w.close()\n\n    var r = try Reader.open(path)\n    expect_eq((try r.read_line()).?, \"first\")\n    expect_eq((try r.read_line()).?, \"second\")\n    expect_eq((try r.read_line()).?, \"third\")\n    expect(try r.read_line() == null)\n    r.close()\n\n    var r2 = try Reader.open(path)\n    expect_eq(try r2.read(3), \"fir\")\n    expect_eq(try r2.read_all(), \"st\\nsecond\\r\\nthird\")\n    r2.close()\n\n    var copy_path = String.from(dir)\n    copy_path.append(\"/nxstream-copy.txt\")\n    var src = try Reader.open(path)\n    var dst = try Writer.open(copy_path)\n    expect_eq(try copy(&mut src, &mut dst), 19)\n    try dst.close()\n    src.close()\n    expect_eq(try io.read_file(copy_path), \"first\\nsecond\\r\\nthird\")\n    try io.remove_file(path)\n    try io.remove_file(copy_path)\n}\n\ntest \"missing file\" {\n    var missing = false\n    _ = Reader.open(\"definitely/not/here.txt\") catch |e| {\n        missing = e == error.NotFound\n        Reader.stdin()\n    }\n    expect(missing)\n}\n";
static const char nx_str_632[8] = "strings";
static const char nx_str_633[8221] = "// std.strings: text utilities on `[]u8` and `String`, written in Nexium.\n//\n// `import std.strings` then `strings.join(parts, \", \")`. The core methods\n// (`len`, `split`, `trim`, `find`, `starts_with`, `parse_int`, ...) are\n// compiler builtins; this module adds what is naturally written in the\n// language itself. Slices returned here point into the argument they were cut\n// from; `String` results are owned by the caller.\n\n/// Concatenate `parts` with `sep` between them.\npub fn join(parts: [][]u8, sep: []u8) -> String {\n    var out = String.new()\n    for p, i in parts {\n        if i > 0 { out.append(sep) }\n        out.append(p)\n    }\n    return out\n}\n\n/// `s` repeated `n` times.\npub fn repeat(s: []u8, n: usize) -> String {\n    var out = String.with_capacity(s.len * n)\n    for _ in 0..n { out.append(s) }\n    return out\n}\n\n/// Left-pad with `fill` to at least `width` bytes.\npub fn pad_left(s: []u8, width: usize, fill: u8) -> String {\n    var out = String.with_capacity(if width > s.len { width } else { s.len })\n    if width > s.len {\n        for _ in 0..width - s.len { out.push_byte(fill) }\n    }\n    out.append(s)\n    return out\n}\n\n/// Right-pad with `fill` to at least `width` bytes.\npub fn pad_right(s: []u8, width: usize, fill: u8) -> String {\n    var out = String.from(s)\n    if width > s.len {\n        for _ in 0..width - s.len { out.push_byte(fill) }\n    }\n    return out\n}\n\n/// Center in `width` bytes, extra fill on the right.\npub fn center(s: []u8, width: usize, fill: u8) -> String {\n    if width <= s.len { return String.from(s) }\n    let total = width - s.len\n    let left = total / 2\n    var out = String.with_capacity(width)\n    for _ in 0..left { out.push_byte(fill) }\n    out.append(s)\n    for _ in 0..total - left { out.push_byte(fill) }\n    return out\n}\n\n/// How many non-overlapping times `needle` occurs in `s`.\npub fn count(s: []u8, needle: []u8) -> usize {\n    if needle.len == 0 or needle.len > s.len { return 0 }\n    var n: usize = 0\n    var i: usize = 0\n    while i + needle.len <= s.len {\n        if s[i..i + needle.len] == needle {\n            n += 1\n            i += needle.len\n        } else {\n            i += 1\n        }\n    }\n    return n\n}\n\n/// Every occurrence of `from` replaced by `to`.\npub fn replace(s: []u8, from: []u8, to: []u8) -> String {\n    var out = String.with_capacity(s.len)\n    if from.len == 0 {\n        out.append(s)\n        return out\n    }\n    var i: usize = 0\n    while i < s.len {\n        if i + from.len <= s.len and s[i..i + from.len] == from {\n            out.append(to)\n            i += from.len\n        } else {\n            out.push_byte(s[i])\n            i += 1\n        }\n    }\n    return out\n}\n\n/// Position of `needle` at or after `start`.\npub fn index_from(s: []u8, needle: []u8, start: usize) -> ?usize {\n    if start > s.len { return null }\n    let rest = s[start..]\n    if let i = rest.find(needle) { return start + i }\n    return null\n}\n\n/// Position of the last occurrence of `needle`.\npub fn last_index(s: []u8, needle: []u8) -> ?usize {\n    if needle.len == 0 or needle.len > s.len { return null }\n    var i = s.len - needle.len + 1\n    while i > 0 {\n        i -= 1\n        if s[i..i + needle.len] == needle { return i }\n    }\n    return null\n}\n\n/// `s` without a leading `prefix`, or null when it does not start with it.\npub fn strip_prefix(s: []u8, prefix: []u8) -> ?[]u8 {\n    if s.starts_with(prefix) { return s[prefix.len..] }\n    return null\n}\n\n/// `s` without a trailing `suffix`, or null when it does not end with it.\npub fn strip_suffix(s: []u8, suffix: []u8) -> ?[]u8 {\n    if s.ends_with(suffix) { return s[0..s.len - suffix.len] }\n    return null\n}\n\nfn is_space(c: u8) -> bool { return c == ' ' or c == '\\t' or c == '\\n' or c == '\\r' }\n\n/// Leading ASCII whitespace removed.\npub fn trim_left(s: []u8) -> []u8 {\n    var i: usize = 0\n    while i < s.len and is_space(s[i]) { i += 1 }\n    return s[i..]\n}\n\n/// Trailing ASCII whitespace removed.\npub fn trim_right(s: []u8) -> []u8 {\n    var n = s.len\n    while n > 0 and is_space(s[n - 1]) { n -= 1 }\n    return s[0..n]\n}\n\n/// True when `s` is empty or only ASCII whitespace.\npub fn is_blank(s: []u8) -> bool {\n    for c in s { if !is_space(c) { return false } }\n    return true\n}\n\n/// Split on runs of ASCII whitespace; no empty pieces.\npub fn split_whitespace(s: []u8) -> List([]u8) {\n    var out = List([]u8).new()\n    var i: usize = 0\n    while i < s.len {\n        while i < s.len and is_space(s[i]) { i += 1 }\n        let start = i\n        while i < s.len and !is_space(s[i]) { i += 1 }\n        if i > start { out.append(s[start..i]) }\n    }\n    return out\n}\n\n/// ASCII letters upper-cased; other bytes unchanged.\npub fn to_upper(s: []u8) -> String {\n    var out = String.with_capacity(s.len)\n    for c in s {\n        if c >= 'a' and c <= 'z' { out.push_byte(c - 32) }\n        else { out.push_byte(c) }\n    }\n    return out\n}\n\n/// ASCII letters lower-cased; other bytes unchanged.\npub fn to_lower(s: []u8) -> String {\n    var out = String.with_capacity(s.len)\n    for c in s {\n        if c >= 'A' and c <= 'Z' { out.push_byte(c + 32) }\n        else { out.push_byte(c) }\n    }\n    return out\n}\n\n/// First ASCII letter upper-cased.\npub fn capitalize(s: []u8) -> String {\n    var out = String.from(s)\n    if s.len > 0 and s[0] >= 'a' and s[0] <= 'z' {\n        out.clear()\n        out.push_byte(s[0] - 32)\n        out.append(s[1..])\n    }\n    return out\n}\n\n/// Bytes in reverse order (bytes, not code points).\npub fn reverse(s: []u8) -> String {\n    var out = String.with_capacity(s.len)\n    var i = s.len\n    while i > 0 {\n        i -= 1\n        out.push_byte(s[i])\n    }\n    return out\n}\n\n/// Cut at the first `sep`: (before, after), or null when `sep` is absent.\npub fn split_once(s: []u8, sep: []u8) -> ?([]u8, []u8) {\n    if let i = s.find(sep) { return (s[0..i], s[i + sep.len..]) }\n    return null\n}\n\n/// Truncate to `max` bytes, appending `...` when something was cut.\npub fn ellipsize(s: []u8, max: usize) -> String {\n    if s.len <= max { return String.from(s) }\n    var out = String.with_capacity(max)\n    if max > 3 { out.append(s[0..max - 3]) }\n    out.append(\"...\")\n    return out\n}\n\ntest \"join and repeat\" {\n    let parts = [\"a\", \"b\", \"c\"]\n    expect_eq(join(parts[..], \", \"), \"a, b, c\")\n    expect_eq(join(parts[0..0], \", \"), \"\")\n    expect_eq(repeat(\"ab\", 3), \"ababab\")\n    expect_eq(repeat(\"x\", 0), \"\")\n}\n\ntest \"padding\" {\n    expect_eq(pad_left(\"7\", 3, '0'), \"007\")\n    expect_eq(pad_right(\"ab\", 4, '.'), \"ab..\")\n    expect_eq(pad_left(\"long\", 2, ' '), \"long\")\n    expect_eq(center(\"hi\", 6, '-'), \"--hi--\")\n    expect_eq(center(\"hi\", 5, '-'), \"-hi--\")\n}\n\ntest \"count and replace\" {\n    expect_eq(count(\"banana\", \"an\"), 2)\n    expect_eq(count(\"aaaa\", \"aa\"), 2)\n    expect_eq(count(\"abc\", \"\"), 0)\n    expect_eq(replace(\"a-b-c\", \"-\", \"+\"), \"a+b+c\")\n    expect_eq(replace(\"aaa\", \"a\", \"bb\"), \"bbbbbb\")\n    expect_eq(replace(\"abc\", \"\", \"x\"), \"abc\")\n}\n\ntest \"searching\" {\n    expect_eq(index_from(\"abcabc\", \"bc\", 2) orelse 99, 4)\n    expect_eq(index_from(\"abc\", \"z\", 0) orelse 99, 99)\n    expect_eq(last_index(\"abcabc\", \"bc\") orelse 99, 4)\n    expect_eq(last_index(\"abc\", \"abcd\") orelse 99, 99)\n    expect_eq(strip_prefix(\"prefix-body\", \"prefix-\") orelse \"none\", \"body\")\n    expect_eq(strip_prefix(\"body\", \"prefix-\") orelse \"none\", \"none\")\n    expect_eq(strip_suffix(\"file.nx\", \".nx\") orelse \"none\", \"file\")\n}\n\ntest \"whitespace\" {\n    expect_eq(trim_left(\"  \\t x \"), \"x \")\n    expect_eq(trim_right(\" x \\n\"), \" x\")\n    expect(is_blank(\" \\t\\n\"))\n    expect(!is_blank(\" a \"))\n    let words = split_whitespace(\"  one two\\tthree\\n\")\n    expect_eq(words.len, 3)\n    expect_eq(words[1], \"two\")\n}\n\ntest \"case and reverse\" {\n    expect_eq(to_upper(\"MiXed 1\"), \"MIXED 1\")\n    expect_eq(to_lower(\"MiXed 1\"), \"mixed 1\")\n    expect_eq(capitalize(\"nexium\"), \"Nexium\")\n    expect_eq(capitalize(\"\"), \"\")\n    expect_eq(reverse(\"abc\"), \"cba\")\n}\n\ntest \"split_once and ellipsize\" {\n    if let kv = split_once(\"key=value=x\", \"=\") {\n        expect_eq(kv.0, \"key\")\n        expect_eq(kv.1, \"value=x\")\n    } else {\n        expect(false)\n    }\n    expect(split_once(\"novalue\", \"=\") == null)\n    expect_eq(ellipsize(\"hello world\", 8), \"hello...\")\n    expect_eq(ellipsize(\"hi\", 8), \"hi\")\n}\n";
static const char nx_str_634[8] = "testing";
static const char nx_str_635[3900] = "// std.testing: conveniences for `test` blocks, written in Nexium.\n//\n// `import std.testing` then, inside a test:\n//\n//     testing.expect_approx(area, 3.14159, 0.001)\n//     testing.expect_err(i32, parse(\"nope\"))\n//     testing.expect_contains(output, \"42 items\")\n//     testing.expect_lines(rendered, expected)    // reports the first differing line\n//     try testing.snapshot(\"report\", rendered)     // compares to snapshots/report.txt\n//\n// Snapshots live in `snapshots/<name>.txt` under the current directory. A\n// missing file is written and the test passes; a mismatch fails with the\n// first differing line. Set `NX_UPDATE_SNAPSHOTS=1` to rewrite them all.\n\nimport std.fs\n\n/// Are two floats within `eps` of each other?\npub fn approx(a: f64, b: f64, eps: f64) -> bool {\n    let d = if a > b { a - b } else { b - a }\n    return d <= eps\n}\n\n/// Panics unless `a` and `b` are within `eps`.\npub fn expect_approx(a: f64, b: f64, eps: f64) {\n    if !approx(a, b, eps) { panic(format(\"expected {} to be within {} of {}\", .{a, eps, b})) }\n}\n\n/// Did the call fail? (Any error counts.)\npub fn is_err(comptime T: type, own r: !T) -> bool {\n    _ = r catch { return true }\n    return false\n}\n\n/// Panics unless the result is an error.\npub fn expect_err(comptime T: type, own r: !T) {\n    if !is_err(T, r) { panic(\"expected an error but the call succeeded\") }\n}\n\n/// Panics unless the result is exactly `err`.\npub fn expect_error(comptime T: type, own r: !T, err: error) {\n    _ = r catch |e| {\n        if e != err { panic(format(\"expected error {} but got {}\", .{err, e})) }\n        return\n    }\n    panic(format(\"expected error {} but the call succeeded\", .{err}))\n}\n\n/// Panics unless `hay` contains `needle`.\npub fn expect_contains(hay: []u8, needle: []u8) {\n    if hay.find(needle) == null { panic(format(\"expected to find {} in {}\", .{needle, hay})) }\n}\n\n/// Compares line by line; panics naming the first line that differs.\npub fn expect_lines(actual: []u8, expected: []u8) {\n    let a = actual.lines()\n    let e = expected.lines()\n    var i: usize = 0\n    while i < a.len and i < e.len {\n        if a[i] != e[i] { panic(format(\"line {} differs:\\n  expected: {}\\n  actual:   {}\", .{i + 1, e[i], a[i]})) }\n        i += 1\n    }\n    if a.len != e.len { panic(format(\"expected {} line(s) but got {}\", .{e.len, a.len})) }\n}\n\n/// Compare `actual` to `<dir>/<name>.txt`; write it when missing or when\n/// NX_UPDATE_SNAPSHOTS is set.\npub fn snapshot_in(dir: []u8, name: []u8, actual: []u8) -> !void {\n    var file = fs.join(dir, name)\n    file.append(\".txt\")\n    let update = os.env(\"NX_UPDATE_SNAPSHOTS\") != null\n    if update or !fs.exists(file) {\n        try fs.make_dirs(dir)\n        try fs.write(file, actual)\n        eprintln(\"wrote snapshot {}\", .{file})\n        return\n    }\n    let expected = try fs.read(file)\n    expect_lines(actual, expected)\n}\n\n/// `snapshot_in(\"snapshots\", name, actual)`.\npub fn snapshot(name: []u8, actual: []u8) -> !void {\n    return snapshot_in(\"snapshots\", name, actual)\n}\n\n// ------------------------------------------------------------------ tests\n\nfn parse_digit(s: []u8) -> !i32 {\n    if s.len != 1 or s[0] < '0' or s[0] > '9' { return error.InvalidInput }\n    return (s[0] - '0') as i32\n}\n\ntest \"floats and errors\" {\n    expect(approx(1.0, 1.0001, 0.001))\n    expect(!approx(1.0, 1.1, 0.001))\n    expect_approx(0.1 + 0.2, 0.3, 0.000001)\n    expect(is_err(i32, parse_digit(\"x\")))\n    expect(!is_err(i32, parse_digit(\"7\")))\n    expect_err(i32, parse_digit(\"nope\"))\n    expect_error(i32, parse_digit(\"nope\"), error.InvalidInput)\n}\n\ntest \"text\" {\n    expect_contains(\"42 items found\", \"items\")\n    expect_lines(\"a\\nb\\n\", \"a\\nb\\n\")\n}\n\ntest \"snapshots\" {\n    let dir = fs.temp_path(\"nxsnap-\")\n    try snapshot_in(dir, \"first\", \"one\\ntwo\\n\")\n    expect(fs.exists(fs.join(dir, \"first.txt\")))\n    try snapshot_in(dir, \"first\", \"one\\ntwo\\n\")\n    try fs.remove_all(dir)\n}\n";
